package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Saves the setting, a dated one from its from-date (none given: the sheet's today); a floor moves the live dues, so
 * the figures it moved are audited after it.
 */
public class SaveSetting {
    public void save(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val SettingInput input,
            Settings settings, SheetClock clock, Audit audit, Rollup rollup) {
        Rollup.Snapshot before = rollup.take(sheet);
        settings.set(sheet, input.key(), input.from() == null ? clock.today(sheet) : input.from(), input.value());
        audit.record("SETTING_CHANGED sheet=" + sheet + " by=" + user + " key=" + input.key() + " value="
                + input.value() + (input.from() == null ? "" : " from=" + input.from()));
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;

/**
 * A validated setting: a known key and its value as stored ("" for the default), and the from-date given for a dated
 * key (null when none was: the sheet's today).
 */
public record SettingInput(String key, String value, LocalDate from) {

    public SettingInput(String key, String value) {
        this(key, value, null);
    }

    /** This setting from the from-date. */
    public SettingInput withFrom(LocalDate from) {
        return new SettingInput(key, value, from);
    }
}
package net.officefloor.hq.app.setting;

/**
 * Body of POST /api/sheets/{sheet}/settings: the setting's key and its new value (blank: its default), and for a dated
 * key the date it is in force from (yyyy-mm-dd; blank: the sheet's today).
 */
public record SettingRequest(String key, String value, String from) {
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;
import java.util.NavigableMap;

/**
 * A figure in force by date: on a date, the value of the latest from-date on or before it, and before every from-date
 * its starting value.
 */
public record Dated(BigDecimal start, NavigableMap<LocalDate, BigDecimal> values) {

    /** The value in force on the date. */
    public BigDecimal on(LocalDate date) {
        Map.Entry<LocalDate, BigDecimal> found = values.floorEntry(date);
        return found == null ? start : found.getValue();
    }

    /** The value in force on the date (yyyy-mm-dd). */
    public BigDecimal on(String date) {
        return on(LocalDate.parse(date));
    }
}
package net.officefloor.hq.app.setting;

import java.util.List;
import java.util.Map;

/**
 * The sheet's settings as the screen shows them: the clerk limit with two decimals, or "" for no limit; and the floor
 * with two decimals; and the terms, a whole number of days; and the late percent with two decimals; and the policy date
 * (yyyy-MM-dd), or "" for the sheet's today; and the period numbering from-date (yyyy-MM-dd), or "" for off; and each grade's own terms (a whole number of days), or "" when it takes the sheet's; and the cap with two decimals, or "" for no cap; and the proof threshold with two decimals, or "" for none; and each action's permitted roles (comma separated), or "" for its standing rule. Each
 * is the value in force on the sheet's today. And, for each dated key, its values as recorded, by from-date. And the grace days (a whole number), or "" for off. And the note threshold
 * with two decimals, or "" for none. And the entry date (yyyy-MM-dd), or "" for off. And each grade's grace (a whole number of days), or "" for none. And each grade's
 * own proof threshold with two decimals, or "" for none (the grade takes the sheet's). And the pot with two decimals,
 * or "" for none. And the parent sheet's id, or "" for none. And the fiscal start month (1 to 12). And the alert
 * threshold with two decimals, or "" for off. And the rounding mode (half-up or half-even), or "" for none. And the review
 * threshold with two decimals, or "" for none. And the escalation gap (a whole number of days), or "" for off. And the review SLA (a whole number of
 * days), or "" for none. And the proof kinds (comma separated), or "" for none. And the default grade, or "" for A. And each grade's own clerk
 * limit with two decimals, or "" for none (the grade takes the sheet's). And the score thresholds of the MID and HIGH
 * bands (whole numbers), each "" for none. And the score log switch, "on" or "" for off. And the
 * maximum of open claims per person (a whole number), or "" for none. And the pending SLA (a whole number of days), or
 * "" for none.
 */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct, String policyDate,
        String periodNumberingFrom, String termsA, String termsB, String termsC, String cap,
        String proofThreshold, Map<String, String> perms, Map<String, List<DatedValue>> dated,
        String graceDays, String noteThreshold, String entryDate, String graceA, String graceB, String graceC,
        String proofThresholdA, String proofThresholdB, String proofThresholdC, String pot, String parent,
        String fiscalStartMonth, String alertThreshold, String rounding, String reviewThreshold, String escalateAfter, String reviewSla, String proofKinds, String defaultGrade,
        String clerkLimitA, String clerkLimitB, String clerkLimitC, String scoreMid, String scoreHigh, String scoreLog, String maxOpen, String pendingSla) {
}
package net.officefloor.hq.app.setting;

import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** Responds with the sheet's settings. */
public class RespondWithSettings {
    public void respond(@PathVariable("sheet") String sheet, Settings settings,
            ObjectResponse<SettingsResponse> response) {
        response.send(settings.all(sheet));
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.hq.app.claim.ProofKind;
import net.officefloor.hq.app.grade.Grades;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.sheet.SheetRegistry;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSetting {
    private static final Pattern LIMIT = Pattern.compile("\\d{1,7}(\\.\\d{1,2})?");
    private static final Pattern SCORE = Pattern.compile("-?\\d{1,7}");
    private static final Pattern DAYS = Pattern.compile("\\d{1,4}");

    public void validate(@PathVariable("sheet") String sheet, @RequestBody SettingRequest request, Settings settings,
            SheetRegistry registry, Grades grades, Out<SettingInput> body) throws InvalidSettingException {
        SettingInput input = input(request);
        if (Settings.DEFAULT_GRADE.equals(input.key()) && !input.value().isEmpty()
                && !grades.isGrade(sheet, input.value())) {
            throw new InvalidSettingException("The default grade must be one of the sheet's grades, or blank");
        }
        if (Settings.PARENT.equals(input.key())) {
            parent(sheet, input.value(), settings, registry);
        }
        // A dated key may be given the date it is in force from; blank: the sheet's today.
        String from = request == null || request.from() == null ? "" : request.from().trim();
        if (Settings.dated(input.key()) && !from.isEmpty()) {
            try {
                input = input.withFrom(LocalDate.parse(from));
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("The from-date must be a date (yyyy-mm-dd), or blank");
            }
        }
        body.set(input);
    }

    /** A parent must be a sheet that exists, not this sheet, nor one that has this sheet as an ancestor; blank: none. */
    private static void parent(String sheet, String parent, Settings settings, SheetRegistry registry)
            throws InvalidSettingException {
        if (parent.isEmpty()) {
            return;
        }
        if (parent.equals(sheet)) {
            throw new InvalidSettingException("A sheet cannot be its own parent");
        }
        if (!registry.exists(parent)) {
            throw new InvalidSettingException("No such sheet: " + parent);
        }
        Set<String> seen = new HashSet<>();
        for (String up = settings.parent(parent); !up.isEmpty() && seen.add(up); up = settings.parent(up)) {
            if (up.equals(sheet)) {
                throw new InvalidSettingException("The sheet " + parent + " has this sheet as an ancestor");
            }
        }
    }

    private SettingInput input(SettingRequest request) throws InvalidSettingException {
        String key = request == null || request.key() == null ? "" : request.key().trim();
        String value = request == null || request.value() == null ? "" : request.value().trim();
